"""Cancellation token for interrupting long-running agent operations."""

from __future__ import annotations

import asyncio
from typing import Awaitable, Optional, TypeVar

import structlog

from rasa.shared.exceptions import RasaException

T = TypeVar("T")

structlogger = structlog.get_logger()

# Bound how long ``race`` waits for a cancelled work task to unwind (e.g. TTS
# stream-end joining an audio sender). Without a cap, "cancel wins" can still
# block on uncooperative teardown.
_TEARDOWN_GRACE_SECONDS = 0.5


class OperationCancelled(RasaException):
    """Raised when a cancellable awaitable is aborted by a cancellation token.

    Distinct from :exc:`asyncio.CancelledError`: the outer turn task is still
    running; only the in-flight LLM / tool / skill await was aborted so the
    orchestrator can stop the turn cleanly.
    """

    def __init__(self, message: str = "Operation cancelled") -> None:
        super().__init__(message)


class CancellationToken:
    """A lightweight, lock-free signaling primitive for cooperative cancellation.

    Wraps an ``asyncio.Event`` so that any external source (session timer,
    channel disconnect, explicit user action) can interrupt a long-running
    operation — such as A2A polling — without acquiring the conversation lock.

    Typical usage inside a polling loop::

        while True:
            ...
            if cancellation_token:
                cancelled = await cancellation_token.wait(timeout=delay)
                if cancelled:
                    break
            else:
                await asyncio.sleep(delay)

    To abort an in-flight awaitable as soon as cancel is signalled::

        result = await token.race(do_work())
    """

    def __init__(self) -> None:
        self._event = asyncio.Event()
        self._cancelled = False
        # Bound on first await so ``cancel()`` can wake waiters via the
        # owning loop (``Event.set()`` is not safe across threads/loops).
        self._loop: Optional[asyncio.AbstractEventLoop] = None

    def _bind_running_loop(self) -> None:
        """Remember the loop that owns waiters for this token.

        Every waiter must call this *before* it checks :attr:`is_cancelled` —
        see the ordering invariant in :meth:`cancel`.
        """
        try:
            running = asyncio.get_running_loop()
        except RuntimeError:
            return
        if self._loop is None:
            self._loop = running

    def cancel(self) -> None:
        """Signal cancellation. Lock-free, safe to call from any thread.

        When waiters are parked on another event loop (e.g. A2A polling in a
        worker thread while a Sanic handler cancels), ``asyncio.Event.set()``
        must run on the owning loop via ``call_soon_threadsafe``. Calling
        ``set()`` directly from a foreign thread can fail to wake waiters and
        can leave ``wait_for`` hung past its timeout.

        Ordering invariant, paired with the waiters: ``_cancelled`` is set
        before ``_loop`` is read here, and every waiter binds the loop before
        it checks :attr:`is_cancelled`. Together these close the window where a
        waiter parks just as this method reads ``_loop`` as ``None`` — one side
        always observes the other's write. Moving either statement reopens the
        window, and the token then silently fails to wake a cross-thread
        waiter.
        """
        self._cancelled = True  # must precede the ``_loop`` read below
        loop = self._loop
        try:
            running = asyncio.get_running_loop()
        except RuntimeError:
            running = None

        if loop is not None and loop.is_running() and running is not loop:
            try:
                loop.call_soon_threadsafe(self._event.set)
                return
            except RuntimeError:
                # Loop closed between the check and the schedule attempt.
                pass
        self._event.set()

    @property
    def is_cancelled(self) -> bool:
        """Non-blocking check."""
        return self._cancelled or self._event.is_set()

    async def wait_until_cancelled(self) -> None:
        """Block indefinitely until cancellation is signalled.

        Unlike :meth:`wait`, this method has no timeout — it returns only
        when :meth:`cancel` has been called.  Use it to create an
        ``asyncio.Task`` that can be raced against another coroutine via
        ``asyncio.wait``::

            consume_task = asyncio.create_task(do_work())
            cancel_task = asyncio.create_task(token.wait_until_cancelled())
            done, pending = await asyncio.wait(
                {consume_task, cancel_task},
                return_when=asyncio.FIRST_COMPLETED,
            )
        """
        self._bind_running_loop()
        if self.is_cancelled:
            self._event.set()
            return
        await self._event.wait()

    async def wait(self, timeout: float) -> bool:
        """Sleep for up to *timeout* seconds, waking immediately on cancellation.

        Use as a cancellation-aware replacement for ``asyncio.sleep`` inside
        polling loops::

            cancelled = await token.wait(timeout=delay)
            if cancelled:
                break

        Returns:
            ``True`` if cancelled before the timeout, ``False`` if the timeout
            expired normally.
        """
        self._bind_running_loop()
        if self.is_cancelled:
            self._event.set()
            return True
        try:
            await asyncio.wait_for(self._event.wait(), timeout=timeout)
            return True
        except asyncio.TimeoutError:
            return False

    async def race(self, awaitable: Awaitable[T]) -> T:
        """Await *awaitable*, aborting when this token is cancelled.

        Raises :exc:`OperationCancelled` when cancel wins (or was already set).
        The losing task is cancelled and drained for up to
        :data:`_TEARDOWN_GRACE_SECONDS` so slow teardown cannot stall the
        caller indefinitely.
        """
        self._bind_running_loop()
        if self.is_cancelled:
            if asyncio.iscoroutine(awaitable):
                awaitable.close()
            raise OperationCancelled()

        work = asyncio.ensure_future(awaitable)
        cancel = asyncio.create_task(self.wait_until_cancelled())
        try:
            done, pending = await asyncio.wait(
                {work, cancel}, return_when=asyncio.FIRST_COMPLETED
            )
        except asyncio.CancelledError:
            await self._cancel_and_drain(work, cancel)
            raise

        await self._cancel_and_drain(*pending)
        if work in done:
            return work.result()
        raise OperationCancelled()

    async def _cancel_and_drain(self, *tasks: asyncio.Task) -> None:
        """Cancel *tasks* and await them up to the teardown grace period."""
        if not tasks:
            return
        for task in tasks:
            task.cancel()
        try:
            await asyncio.wait_for(
                asyncio.gather(*tasks, return_exceptions=True),
                timeout=_TEARDOWN_GRACE_SECONDS,
            )
        except asyncio.TimeoutError:
            structlogger.warning(
                "cancellation.race.teardown_timeout",
                grace_seconds=_TEARDOWN_GRACE_SECONDS,
                pending_count=sum(1 for task in tasks if not task.done()),
            )
